import os, re, json

# Load all grids from session
d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]
print("Grids loaded:", sorted(G.keys()))
for k, v in G.items():
    print(f"\n{k}={v}")

def transform(grid):
    """Transform 18x18 grid to 6x6 by taking the unique non-5 color from each 3x3 block."""
    h = len(grid)
    w = len(grid[0])
    oh, ow = h // 3, w // 3

    output = [[0] * ow for _ in range(oh)]

    for i in range(oh):
        for j in range(ow):
            # Get all values in the 3x3 block
            colors = set()
            for di in range(3):
                for dj in range(3):
                    val = grid[i*3 + di][j*3 + dj]
                    colors.add(val)

            # Non-5 color is the output (or 0 if only 0s)
            non_5_colors = colors - {5}
            if not non_5_colors:
                # All 5s
                output[i][j] = 5
            elif 0 in non_5_colors:
                output[i][j] = 0
            else:
                # Single non-5 color
                output[i][j] = list(non_5_colors)[0]

    return output

